815→// resolveTranscriptOffset determines the transcript offset to use for parsing.
816→// Prefers pre-prompt state, falls back to session state.
817→func resolveTranscriptOffset(ctx context.Context, preState *PrePromptState, sessionID string) int {
818→	logCtx := logging.WithComponent(ctx, "lifecycle")
819→	if preState != nil && preState.TranscriptOffset > 0 {
820→		logging.Debug(logCtx, "pre-prompt state found, parsing transcript from offset",
821→			slog.Int("offset", preState.TranscriptOffset))
822→		return preState.TranscriptOffset
823→	}
824→
825→	// Fall back to session state
826→	sessionState, loadErr := strategy.LoadSessionState(ctx, sessionID)
827→	if loadErr != nil {
828→		logging.Warn(logCtx, "failed to load session state",
829→			slog.String("error", loadErr.Error()))
830→		return 0
831→	}
832→	if sessionState != nil && sessionState.CheckpointTranscriptStart > 0 {
833→		logging.Debug(logCtx, "session state found, parsing transcript from offset",
834→			slog.Int("offset", sessionState.CheckpointTranscriptStart))
835→		return sessionState.CheckpointTranscriptStart
836→	}
837→
838→	return 0
839→}
