// Clear checkpoint IDs on every new prompt.
// LastCheckpointID is set during PostCommit, cleared at new prompt.
// TurnCheckpointIDs tracks mid-turn checkpoints for stop-time finalization.
state.LastCheckpointID = ""
state.TurnCheckpointIDs = nil

// Advance CheckpointTranscriptStart when prior turns were not condensed.
// Without this, CheckpointTranscriptStart stays at the value from the last
// condensation, causing the next checkpoint's scoped transcript to include
// prior turns' content — even though prompt.txt and TurnID only reflect the
// current turn. Advance to current transcript position so the scoped window
// matches the metadata.
if state.StepCount > 0 && state.TranscriptPath != "" {
	if ag, agErr := agent.GetByAgentType(state.AgentType); agErr == nil {
		if analyzer, ok := agent.AsTranscriptAnalyzer(ag); ok {
			if pos, posErr := analyzer.GetTranscriptPosition(state.TranscriptPath); posErr == nil && pos > state.CheckpointTranscriptStart {
				logging.Debug(logging.WithComponent(ctx, "hooks"),
					"advancing CheckpointTranscriptStart past un-condensed turns",
					slog.String("session_id", sessionID),
					slog.Int("old_offset", state.CheckpointTranscriptStart),
					slog.Int("new_offset", pos),
					slog.Int("un_condensed_steps", state.StepCount),
				)
				state.CheckpointTranscriptStart = pos
			}
		}
	}
}

