//go:build integration

package integration

import (
	"encoding/json"
	"testing"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

// TestCheckpointTranscriptStart_AdvancesPastUncondensedTurns verifies that
// checkpoint_transcript_start correctly advances when intermediate turns
// happen between commits.
//
// Reproduces a bug observed with Codex sessions where:
// - Turn N modifies files, Stop fires, no commit
// - Turn N+1 triggers a commit
// - The condensed checkpoint's checkpoint_transcript_start was stuck at the
//   value from the PREVIOUS condensation, incorrectly including Turn N's
//   content in Turn N+1's scoped transcript.
//
// The correct behavior: checkpoint_transcript_start should advance past
// un-condensed turns so the scoped transcript matches the checkpoint's
// prompt and turn metadata.
func TestCheckpointTranscriptStart_AdvancesPastUncondensedTurns(t *testing.T) {
	t.Parallel()
	env := NewFeatureBranchEnv(t)

	session := env.NewSession()

	// ============================
	// Turn 1: Modify files, commit
	// ============================
	t.Log("Turn 1: Create file, stop, commit")

	// UserPromptSubmit with transcript path so CapturePrePromptState records offset
	if err := env.SimulateUserPromptSubmitWithPromptAndTranscriptPath(
		session.ID, "Create auth module", session.TranscriptPath,
	); err != nil {
		t.Fatalf("Turn 1 UserPromptSubmit failed: %v", err)
	}

	// Agent creates a file
	env.WriteFile("auth.go", "package auth\n\nfunc Login() {}\n")

	// Build transcript for Turn 1
	session.CreateTranscript("Create auth module", []FileChange{
		{Path: "auth.go", Content: "package auth\n\nfunc Login() {}\n"},
	})

	// Stop fires, creating a checkpoint on the shadow branch
	if err := env.SimulateStop(session.ID, session.TranscriptPath); err != nil {
		t.Fatalf("Turn 1 Stop failed: %v", err)
	}

	// User commits — triggers condensation
	env.GitCommitWithShadowHooks("Add auth module", "auth.go")

	// Record transcript line count after Turn 1's condensation
	state1, err := env.GetSessionState(session.ID)
	require.NoError(t, err)
	require.NotNil(t, state1)
	transcriptStartAfterCommit1 := state1.CheckpointTranscriptStart
	t.Logf("After commit 1: CheckpointTranscriptStart=%d, StepCount=%d",
		state1.CheckpointTranscriptStart, state1.StepCount)

	// Verify checkpoint 1 was condensed
	checkpointID1 := env.GetCheckpointIDFromCommitMessage(env.GetHeadHash())
	require.NotEmpty(t, checkpointID1, "First commit should have checkpoint trailer")

	// ====================================
	// Turn 2: Modify files, stop, NO commit
	// ====================================
	t.Log("Turn 2: Modify file, stop, but do NOT commit")

	if err := env.SimulateUserPromptSubmitWithPromptAndTranscriptPath(
		session.ID, "Update README", session.TranscriptPath,
	); err != nil {
		t.Fatalf("Turn 2 UserPromptSubmit failed: %v", err)
	}

	// Agent modifies a file
	env.WriteFile("README.md", "# Updated README\n\nNew content from Turn 2.\n")

	// Build transcript for Turn 2 (appends to existing transcript)
	session.CreateTranscript("Update README", []FileChange{
		{Path: "README.md", Content: "# Updated README\n\nNew content from Turn 2.\n"},
	})

	// Stop fires — creates checkpoint on shadow branch
	if err := env.SimulateStop(session.ID, session.TranscriptPath); err != nil {
		t.Fatalf("Turn 2 Stop failed: %v", err)
	}

	// Record state after Turn 2 Stop — NO commit happens
	state2, err := env.GetSessionState(session.ID)
	require.NoError(t, err)
	require.NotNil(t, state2)
	t.Logf("After Turn 2 stop (no commit): CheckpointTranscriptStart=%d, StepCount=%d",
		state2.CheckpointTranscriptStart, state2.StepCount)

	// StepCount should be 1 (one un-condensed step from Turn 2)
	assert.Equal(t, 1, state2.StepCount, "Should have 1 un-condensed step after Turn 2")

	// ==========================================
	// Turn 3: Trigger commit (like "commit/push")
	// ==========================================
	t.Log("Turn 3: Commit the changes (like 'commit/push' prompt)")

	if err := env.SimulateUserPromptSubmitWithPromptAndTranscriptPath(
		session.ID, "commit/push", session.TranscriptPath,
	); err != nil {
		t.Fatalf("Turn 3 UserPromptSubmit failed: %v", err)
	}

	// Record state after Turn 3's UserPromptSubmit to check if offset advanced
	state3, err := env.GetSessionState(session.ID)
	require.NoError(t, err)
	require.NotNil(t, state3)
	t.Logf("After Turn 3 UserPromptSubmit: CheckpointTranscriptStart=%d, StepCount=%d",
		state3.CheckpointTranscriptStart, state3.StepCount)

	// No file changes in Turn 3 — the agent just commits existing staged changes.
	// Build transcript for Turn 3 (just a commit message, no tool use for files)
	session.TranscriptBuilder.AddUserMessage("commit/push")
	session.TranscriptBuilder.AddAssistantMessage("I'll commit and push the changes.")
	session.TranscriptBuilder.AddAssistantMessage("Done! Changes committed and pushed.")
	if err := session.TranscriptBuilder.WriteToFile(session.TranscriptPath); err != nil {
		t.Fatalf("Failed to write Turn 3 transcript: %v", err)
	}

	// Stop fires for Turn 3 (no new file modifications, checkpoint may be skipped)
	if err := env.SimulateStop(session.ID, session.TranscriptPath); err != nil {
		t.Fatalf("Turn 3 Stop failed: %v", err)
	}

	// User commits the README changes from Turn 2
	env.GitCommitWithShadowHooks("Update README", "README.md")

	// Get the second checkpoint ID
	checkpointID2 := env.GetCheckpointIDFromCommitMessage(env.GetHeadHash())
	require.NotEmpty(t, checkpointID2, "Second commit should have checkpoint trailer")

	// ==========================================
	// ASSERTION: checkpoint_transcript_start should have advanced
	// ==========================================
	t.Log("Verifying checkpoint_transcript_start in condensed metadata")

	// Read the session-level metadata from the metadata branch
	metadataPath := SessionMetadataPath(checkpointID2)
	content, found := env.ReadFileFromBranch(paths.MetadataBranchName, metadataPath)
	require.True(t, found, "Session metadata should exist for checkpoint %s at %s", checkpointID2, metadataPath)

	var metadata checkpoint.CommittedMetadata
	require.NoError(t, json.Unmarshal([]byte(content), &metadata))

	t.Logf("Checkpoint 2 metadata: checkpoint_transcript_start=%d", metadata.TranscriptStartOffset())
	t.Logf("Transcript start after commit 1: %d", transcriptStartAfterCommit1)

	// BUG: Without the fix, checkpoint_transcript_start will equal
	// transcriptStartAfterCommit1 (from the first condensation), which means
	// the scoped transcript includes Turn 2's "Update README" content even
	// though the checkpoint's prompt is "commit/push" (Turn 3).
	//
	// EXPECTED: checkpoint_transcript_start should be GREATER than
	// transcriptStartAfterCommit1, advancing past Turn 2's content.
	assert.Greater(t, metadata.TranscriptStartOffset(), transcriptStartAfterCommit1,
		"checkpoint_transcript_start should advance past un-condensed Turn 2 content; "+
			"got %d which is the same as after commit 1 (%d), meaning Turn 2's "+
			"'Update README' content is incorrectly included in Turn 3's checkpoint",
		metadata.TranscriptStartOffset(), transcriptStartAfterCommit1)
}

